"""
fix_test_telegram_otp.py — Corrige un test qui supposait TELEGRAM_BOT_TOKEN
absent de l'environnement (faux sur ta machine : le .env contient déjà un
vrai token pour les notifications de groupe). Ne touche que
tests/test_api.py -- le reste du patch précédent (deploy_telegram_otp.py)
n'a pas besoin d'être relancé.
"""

import base64
import os

RACINE = os.path.dirname(os.path.abspath(__file__))

CONTENU_B64 = """"""

chemin = os.path.join(RACINE, "tests", "test_api.py")
with open(chemin, "wb") as f:
    f.write(base64.b64decode(CONTENU_B64))

print("écrit : tests/test_api.py")
print()
print("Terminé. Lance maintenant : pytest -q")
